        "hanzi": "加油，我相信你一定能做到。",
        "pinyin": "Jiāyóu, wǒ xiāngxìn nǐ yīdìng néng zuò dào.",
        "meaning": "Cố lên, mình tin bạn nhất định sẽ làm được.",
