    "lines": [
      {
        "speaker": "A: Tiểu Minh",
        "hanzi": "你好，我想看看这件羽绒服，可以试穿一下吗？",
        "pinyin": "Nǐ hǎo, wǒ xiǎng kànkan zhè jiàn yǔróngfú, kěyǐ shìchuān yíxià ma?",
        "meaning": "Chào bạn, tôi muốn xem chiếc áo lông vũ này, có thể mặc thử một chút không?",
        "highlight": "试穿 (shìchuān - mặc thử)",
        "grammarLink": ""
      },
      {
        "speaker": "B: Tiểu Hoa",
        "hanzi": "当然可以，您穿多大码的？这件是M码，您可能需要L码。",
        "pinyin": "Dāngrán kěyǐ, nín chuān duō dà mǎ de? Zhè jiàn shì M mǎ, nín kěnéng xūyào L mǎ.",
        "meaning": "Tất nhiên được, bạn mặc size bao nhiêu? Cái này size M, bạn có thể cần size L.",
        "highlight": "码 (mǎ - size, cỡ)",
        "grammarLink": ""
      },
      {
        "speaker": "A: Tiểu Minh",
        "hanzi": "我平时穿L码的。这件衣服是什么面料的？摸起来很舒服。",
        "pinyin": "Wǒ píngshí chuān L mǎ de. Zhè jiàn yīfu shì shénme miànliào de? Mō qǐlai hěn shūfu.",
        "meaning": "Tôi thường mặc size L. Chiếc áo này chất liệu gì vậy? Sờ vào rất thoải mái.",
        "highlight": "面料 (miànliào - chất liệu vải)",
        "grammarLink": ""
      },
      {
        "speaker": "B: Tiểu Hoa",
        "hanzi": "这是今年流行的防水面料，既保暖又实用。您要试试L码的吗？",
        "pinyin": "Zhè shì jīnnián liúxíng de fángshuǐ miànliào, jì bǎonuǎn yòu shíyòng. Nín yào shìshi L mǎ de ma?",
        "meaning": "Đây là chất liệu chống nước đang thịnh hành năm nay, vừa giữ ấm vừa thực dụng. Bạn muốn thử size L không?",
        "highlight": "防水 (fángshuǐ - chống nước)",
        "grammarLink": ""
      },
      {
        "speaker": "A: Tiểu Minh",
        "hanzi": "好的，麻烦你拿一件L码的给我试试。另外，这件打几折？",
        "pinyin": "Hǎo de, máfan nǐ ná yí jiàn L mǎ de gěi wǒ shìshi. Lìngwài, zhè jiàn dǎ jǐ zhé?",
        "meaning": "Được, phiền bạn lấy một cái size L cho tôi thử. Ngoài ra, cái này giảm giá bao nhiêu?",
        "highlight": "打折 (dǎzhé - giảm giá)",
        "grammarLink": ""
      },
      {
        "speaker": "B: Tiểu Hoa",
        "hanzi": "现在换季促销，全场八折。这件原价八百，打完折六百四。",
        "pinyin": "Xiànzài huànjì cùxiāo, quánchǎng bā zhé. Zhè jiàn yuánjià bābǎi, dǎ wán zhé liùbǎi sì.",
        "meaning": "Hiện đang khuyến mãi chuyển mùa, toàn bộ giảm 20%. Cái này giá gốc 800, sau giảm còn 640.",
        "highlight": "原价 (yuánjià - giá gốc)",
        "grammarLink": ""
      },
      {
        "speaker": "A: Tiểu Minh",
        "hanzi": "价格还可以。我试穿一下，如果合适就买了。",
        "pinyin": "Jiàgé hái kěyǐ. Wǒ shìchuān yíxià, rúguǒ héshì jiù mǎi le.",
        "meaning": "Giá cũng được. Tôi mặc thử một chút, nếu vừa thì mua.",
        "highlight": "合适 (héshì - phù hợp, vừa)",
        "grammarLink": ""
      },
      {
        "speaker": "B: Tiểu Hoa",
        "hanzi": "好的，试衣间在那边。有什么需要随时叫我。",
        "pinyin": "Hǎo de, shìyījiān zài nàbiān. Yǒu shénme xūyào suíshí jiào wǒ.",
        "meaning": "Được, phòng thử đồ ở đằng kia. Có nhu cầu gì cứ gọi tôi bất cứ lúc nào.",
        "highlight": "试衣间 (shìyījiān - phòng thử đồ)",
        "grammarLink": ""
      }
    ],
