        "speaker": "A: Du khách",
        "hanzi": "谢谢您的时间，期待您的回复。",
        "pinyin": "Xièxie nín de shíjiān, qídài nín de huífù.",
        "meaning": "Cảm ơn thời gian của ông, mong chờ hồi âm của ông.",
        "highlight": "回复 (huífù - hồi âm, trả lời)",
