        "pinyin": "Dāngrán kěyǐ, rúguǒ nín chéngwéi wǒmen de huìyuán, kěyǐ xiǎngshòu jiǔ zhé yōuhuì, hái zèngsòng yī cì miǎnfèi jiējī fúwù.",
        "meaning": "Tất nhiên có thể, nếu ngài trở thành hội viên của chúng tôi, có thể được hưởng giảm giá 10%, còn tặng thêm một lần dịch vụ đón sân bay miễn phí.",
