    "id": "ai_d_hsk6_1785174991740_2",
    "title": "Khám bệnh và sức khỏe",
    "level": "HSK 6",
    "description": "Tiểu Trần cảm thấy mệt mỏi và đau đầu, đến bệnh viện khám và được bác sĩ tư vấn.",
