        "pinyin": "Yīshēng, wǒ zuìjìn zǒng shì tóuyūn fálì, wǎnshang yě shuì bù hǎo, nín kàn wǒ zhè shì zěnme le?",
        "meaning": "Bác sĩ, gần đây tôi thường xuyên chóng mặt mệt mỏi, tối cũng ngủ không ngon, bác xem tôi bị sao vậy?",
