        "hanzi": "您好，我想预订一间双人房，下周五入住，住三个晚上。",
        "pinyin": "Nín hǎo, wǒ xiǎng yùdìng yī jiān shuāngrén fáng, xià zhōuwǔ rùzhù, zhù sān ge wǎnshang.",
        "meaning": "Xin chào, tôi muốn đặt một phòng đôi, nhận phòng thứ Sáu tuần sau, ở ba đêm.",
        "highlight": "预订 (yùdìng - đặt trước)",
