        "speaker": "B: Đồng nghiệp",
        "hanzi": "没问题，我们有专车接送，但需要额外收费。另外，您是否需要旅游咨询？我们可以推荐当地特色路线。",
        "pinyin": "Méi wèntí, wǒmen yǒu zhuānchē jiēsòng, dàn xūyào éwài shōufèi. Lìngwài, nín shìfǒu xūyào lǚyóu zīxún? Wǒmen kěyǐ tuījiàn dāngdì tèsè lùxiàn.",
        "meaning": "Không vấn đề, chúng tôi có xe đưa đón riêng, nhưng cần thu thêm phí. Ngoài ra, ông có cần tư vấn du lịch không? Chúng tôi có thể giới thiệu các tuyến đặc sắc địa phương.",
