        "hanzi": "喂，是李明吗？好久不见，你最近怎么样？",
        "pinyin": "Wèi, shì Lǐ Míng ma? Hǎojiǔ bùjiàn, nǐ zuìjìn zěnmeyàng?",
        "meaning": "Alô, có phải Lý Minh không? Lâu quá không gặp, dạo này bạn thế nào?",
